import time
from functools import wraps

def rate_limits(max_interval=60):
	def decorator(func):
		@wraps(func)
		def wrapper(*args, **kwargs):
			current_time = time.time()
			# Check if function has cooldown attribute and is within cooldown period
			if hasattr(func, 'last_run') and (current_time - func.last_run) < max_interval:
				# Skip execution for cooldown duration
				return None
			# Update last_run time and execute function
			func.last_run = current_time
			return func(*args, **kwargs)
		return wrapper

