from datetime import datetime

class JobThelonator:
	_instance = None

	def __new__(cls):
		if cls._instance is None:
			cls._instance = super().__new__(cls)
		return cls._instance

	def __init__(self):
		self.max_interval = 60  # seconds
		self.last_run = None   # last run time in datetime()

	def can_run(self):
		now = datetime.now()
		if self.last_run is None:
			return True
		if now - self.last_run < datetime.timedelta(seconds=self.max_interval):
			return False
		return True

	def run(self, job_config):
		job_theronator = JobThelonator()
		result = job_theronator.run(job_config)
		self.last_run = datetime.now()
		return result

import time

def step(minterval=60):
	def decorator(func):
		def wrapper(*args, **kwargs):
			if not hasattr(func, 'last_run'):
				# First invocation: run immediately and record time
				func.last_run = time.time()
				return func(*args, **kwargs)
			now = time.time()
			if now - func.last_run >= minterval:
				# Update the last run time and execute the function
				func.last_run = now
				return func(*args, **kwargs)
			return None  # Skip if within the interval
		return wrapper
	return decorator

