def column_stats(table):
	if not table:
		return {}

	header = table[0]
	data = table[1:]

	if not data:
		return {col: {'mean': 0.0, 'median': 0.0, 'mode': None, 'variance': 0.0} for col in header}

	col_data = {}
	for i in range(len(header)):
		col_data[header[i]] = []

	for row in data:
		for j, val in enumerate(row):
			col_data[header[j]].append(float(val))

	res = {}
	for col in header:
		values = col_data[col]
		n = len(values)

		mean_val = sum(values) / n

		freq = {}
		for v in values:
			freq[v] = freq.get(v, 0) + 1
		mode_val = max(freq, key=freq.get)

		sorted_vals = sorted(values)
		if n % 2 == 1:
			median_val = sorted_vals[n//2]
		else:
			median_val = (sorted_vals[n//2 - 1] + sorted_vals[n//2]) / 2

		squared_diffs = [(x - mean_val) ** 2 for x in values]
		variance_val = sum(squared_diffs) / n

		res[col] = {
			'mean': mean_val,
			'median': median_val,
			'mode': mode_val,
			'variance': variance_val
		}

	return res

def column_stats(table):
	if not table:
		return {}
	header = table[0]
	n_rows = len(table)
	if n_rows == 1:
		return {col: {'mean': 0, 'median': 0, 'mode': None, 'variance': 0} for col in header}

	result_dict = {}
	for j in range(len(header)):
		col_data = [table[i][j] for i in range(1, n_rows)]
		col_data = [float(x) for x in col_data]
		n = len(col_data)
		if n == 0:
			result_dict[header[j]] = {'mean': 0, 'median': 0, 'mode': None, 'variance': 0}
		else:
			mean_val = sum(col_data) / n
			sorted_data = sorted(col_data)
			if n % 2 == 1:
				median_val = sorted_data[n // 2]
			else:
				median_val = (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2
			freq = {}
			for x in col_data:
				freq[x] = freq.get(x, 0) + 1
			max_freq = max(freq.values())
			for x in col_data:
				if freq[x] == max_freq:
					mode_val = x
					break
			variance_val = sum((x - mean_val) ** 2 for x in col_data) / n
			result_dict[header[j]] = {
				'mean': mean_val,
				'median': median_val,
				'mode': mode_val,
				'variance': variance_val
			}
	return result_dict

