import tempfile

def decompress(source: str, target: str = None) -> str:
	if source.startswith('http') or source.startswith('https') or source.startswith('ftp'):
		try:
			with urllib.request.urlopen(source) as response:
				with tempfile.TemporaryFile(mode='w+b') as f:
					f.write(response.read())
					f.seek(0)
					source = f.name
		except Exception as e:
			raise ValueError(f"Failed to download {source}: {e}")

	decoded_files = False
	content = ''
	if source.endswith('.zip'):
		try:
			with zipfile.ZipFile(source, 'r') as zip_ref:
				for file in zip_ref.namelist():
					with zip_ref.open(file) as f:
						data = f.read()
						try:
							s = data.decode('utf-8').strip()
							content += s
							decoded_files = True
						except UnicodeDecodeError:
							raise UnicodeDecodeError(f"Failed to decode '{file}' as UTF-8")
		except Exception as e:
			if decoded_files:
				return content
			raise ValueError(f"Failed to decompress {source}: {e}")
	elif source.endswith('.xz'):
		try:
			with lzma.open(source, 'rb') as f:
				data = f.read()
				content = data.decode('utf-8').strip()
		except Exception as e:
			raise ValueError(f"Failed to decompress {source} with lzma: {e}")
	elif source.endswith('.gz') or source.endswith('.gzip'):
		try:
			with gzip.open(source, 'rb') as f:
				data = f.read()
				content = data.decode('utf-8').strip()
		except Exception as e:
			raise ValueError(f"Failed to decompress {source} with gzip: {e}")
	else:
		raise ValueError(f"Unsupported compression format: {os.path.normpath(source)}")

	return content

