from scipy.spatial import KDTree
from collections import deque

def main():
	data = [line.strip() for line in sys.stdin if line.strip()]
	if not data:
		return

	try:
		n = int(data[0])
		points = []
		for i in range(1, 1 + n):
			parts = data[i].split()
			if len(parts) < 2:
				continue
			x = float(parts[0])
			y = float(parts[1])
			points.append((x, y))
		if len(data) < n + 3:
			return
		max_radius = float(data[n + 1])
		min_size = int(data[n + 2])
	except Exception:
		return

	tree = KDTree(points)
	n_points = len(points)
	visited = [False] * n_points
	clusters = []

	for i in range(n_points):
		if not visited[i]:
			queue = deque([i])
			visited[i] = True
			comp = [i]
			while queue:
				idx = queue.popleft()
				neighbors = tree.query_ball_point(points[idx], max_radius)
				for nbr in neighbors:
					if not visited[nbr]:
						visited[nbr] = True
						queue.append(nbr)
						comp.append(nbr)
			if len(comp) >= min_size:
				clusters.append(comp)

	for cluster in clusters:
		cluster.sort()
		line = ' '.join(f"{points[i][0]} {points[i][1]}" for i in cluster)
		print(line)

if __name__ == "__main__":
	main()

import sys

def main():
	data = sys.stdin.read().splitlines()
	if not data:
		return

	parts = data[0].split()
	if len(parts) < 2:
		return
	try:
		radius_val = float(parts[0])
		min_size_val = int(parts[1])
	except:
		print("Invalid first line: must have radius and min_size")
		return

	points = []
	for i in range(1, len(data)):
		line = data[i].strip()
		if not line:
			continue
		parts = line.split()
		if len(parts) < 2:
			continue
		x = float(parts[0])
		y = float(parts[1])
		points.append((x, y))

	n = len(points)
	if n == 0:
		return

	visited = [False] * n
	radius_sq = radius_val * radius_val
	clusters = []

	for i in range(n):
		if visited[i]:
			continue
		stack = [i]
		visited[i] = True
		current_cluster = []

		while stack:
			idx = stack.pop()
			current_cluster.append(points[idx])
			x1, y1 = points[idx]
			for j in range(n):
				if visited[j]:
					continue
				x2, y2 = points[j]
				dx = x1 - x2
				dy = y1 - y2
				dist_sq = dx*dx + dy*dy
				if dist_sq <= radius_sq:
					visited[j] = True
					stack.append(j)

		if len(current_cluster) >= min_size_val:
			clusters.append(current_cluster)

	for cluster in clusters:
		for point in cluster:
			print(f"{point[0]} {point[1]}")

if __name__ == '__main__':
	main()

from html.parser import HTMLParser
import urllib.parse

class LinkExtractor(HTMLParser):
	def __init__(self):
		super().__init__()
		self.base = None
		self.links = []

	def handle_starttag(self, name, attrs):
		if name == 'base':
			if self.base is None:
				for attr in attrs:
					if attr[0] == 'href' and attr[1] is not None:
						self.base = attr[1]
						break
		elif name in ['a', 'area']:
			for attr in attrs:
				if attr[0] == 'href' and attr[1] is not None:
					url = attr[1]
					if self.base is not None:
						url = urllib.parse.urljoin(self.base, url)
					self.links.append(url)

def extract_links(html):
	parser = LinkExtractor()
	parser.feed(html)
	return parser.links

