import click

class HTMLLinkParser(HTMLParser):
	def __init__(self, base_url):
		super().__init__()
		self.base_url = base_url
		self.links = set()

	def handle_starttag(self, tag, attrs):
		if tag == 'base':
			for name, value in attrs:
				if name == 'href':
					self.base_url = urllib.parse.urljoin(self.base_url, value)
		else:
			for name, value in attrs:
				if name == 'href':
					url = urllib.parse.urljoin(self.base_url, value)
					self.links.add(url)

	def handle_startendtag(self, tag, attrs):
		for name, value in attrs:
			if name == 'href':
				url = urllib.parse.urljoin(self.base_url, value)
				self.links.add(url)

def extract_links(url):
	try:
		req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
		res = urllib.request.urlopen(req, timeout=5)
		html = res.read().decode('utf-8')
		parser = HTMLLinkParser(url)
		parser.feed(html)
		parser.close()
		sorted_links = sorted(parser.links)
		for link in sorted_links:
			click.echo(link)
	except urllib.error.HTTPError as e:
		click.echo(f"HTTP Error: {e.code}")
	except urllib.error.URLError as e:
		click.echo(f"URL Error: {e.reason}")
	except Exception as e:
		click.echo(f"Error: {str(e)}")
		sys.exit(1)

