def flatten(lst):
	stack = [iter(lst)]
	result = []
	while stack:
		current = next(stack[-1], None)
		if current is None:
			stack.pop()
		elif isinstance(current, list):
			stack.append(iter(current))
		else:
			result.append(current)
	return result

