from toolbox.utils import read_text, write_text

def tokenize_text(text):
	if hasattr(text, 'read'):
		text = text.read()

	sentences = []
	temp = ''
	for char in text:
		if char in '.!?':
			if temp:
				sentences.append(temp)
				temp = ''
		else:
			temp += char
	if temp:
		sentences.append(temp)
	return [s.split() for s in sentences]

