def tokenize_sentences(
	path: str | Path,
) -> list[list[str]]:
	text = read_text(path)
	sentences = [s.strip() for s in re.split(r'[.!?]', text) if s.strip()]
	tokens = []
	for sentence in sentences:
		words = sentence.split()
		tokens.append(words)
	return tokens

def standardize_within_group(data, value_col, group_col):
	if len(data) == 0:
		return []

	first_record = data[0]
	if value_col not in first_record or group_col not in first_record:
		return data

	group_col_index = first_record.index(group_col)
	value_col_index = first_record.index(value_col)

	groups_dict = {}
	for record in data:
		group_val = record[group_col_index]
		value_val = record[value_col_index]
		if group_val not in groups_dict:
			groups_dict[group_val] = []
		groups_dict[group_val].append(value_val)

	mean_std_map = {}
	for key, values in groups_dict.items():
		n = len(values)
		if n == 1:
			mean_std_map[key] = (values[0], 0)
		else:
			mean_val = sum(values) / n
			variance = sum((x - mean_val) ** 2 for x in values) / n
			std_val = variance ** 0.5
			mean_std_map[key] = (mean_val, std_val)

	result = []
	for record in data:
		group_val = record[group_col_index]
		value_val = record[value_col_index]
		mean, std = mean_std_map[group_val]
		if std == 0:
			z = 0
		else:
			z = (value_val - mean) / std
		new_record = record.copy()
		new_record[value_col_index] = z
		result.append(new_record)

	return result

def standardize_within_group(data, value_col, group_col):
	groups = {}
	for record in data:
		key = record.get(group_col)
		if key is None:
			continue
		if key not in groups:
			groups[key] = []
		groups[key].append(record.get(value_col))

	group_stats = {}
	for key, values in groups.items():
		n = len(values)
		if n == 1:
			group_stats[key] = (values[0], 0.0)
		else:
			mean_val = sum(values) / n
			sq_diff = sum((x - mean_val) ** 2 for x in values)
			std_dev = (sq_diff / n) ** 0.5
			group_stats[key] = (mean_val, std_dev)

	result = []
	for record in data:
		key = record.get(group_col)
		if key is None:
			result.append(record.copy())
			continue
		mean_val, std_dev = group_stats.get(key, (0.0, 0.0))
		if std_dev == 0.0:
			z_score = 0.0
		else:
			z_score = (record[value_col] - mean_val) / std_dev
		new_record = record.copy()
		new_record[value_col] = z_score
		result.append(new_record)
	return result

import math

def standardize_within_group(records, value_col, group_col):
	if not records:
		return []

	groups = {}
	for r in records:
		key = r[group_col]
		if key not in groups:
			groups[key] = []
		groups[key].append(r)

	new_records = []
	for group in groups.values():
		values = [record[value_col] for record in group]
		n = len(values)
		if n == 0:
			continue
		if n == 1:
			for record in group:
				new_record = record.copy()
				new_record[value_col] = 0.0
				new_records.append(new_record)
		else:
			mean = sum(values) / n
			variance = sum((x - mean) ** 2 for x in values) / n
			std = math.sqrt(variance)
			for record in group:
				new_record = record.copy()
				z_value = (record[value_col] - mean) / std
				new_record[value_col] = z_value
				new_records.append(new_record)

	return new_records

