		if key not in groups:
			groups[key] = []
		groups[key].append(record[value_column])

	group_stats = {}
	for key, values in groups.items():
		n = len(values)
		if n == 1:
			mean = 0
			std = 0
		else:
			mean = sum(values) / n
			std = (sum((x - mean) ** 2 for x in values) ** 0.5
		group_stats[key] = (mean, std)

	result = []
	for record in data:
		key = record[group_column]
		value = record[value_column]
		mean, std = group_stats[key]
		if std == 0:
			z_score = 0.0
		else:
			z_score = (value - mean) / std
		new_record = record.copy()
		new_record[value_column] = z_score
		result.append(new_record)

	return result

