		super().__init__()
		self.url = url
		self.base = url
		self.links = []

	def handle_starttag(self, tag, attrs):
		if tag == 'base':
			for name, value in attrs:
				if name == 'href':
					self.base = value
			return

		for name, value in attrs:
			if name == 'href':
				if self.base is not None and not value.startswith('http'):
					value = self.base + value
				self.links.append(value)

