import time
from pathlib import Path

class FileWatcher:
	def __init__(self, path, callback=None):
		self.path = Path(path)
		self.callback = callback

		self.exists_state = 'exists' if self.path.exists() else 'does_not_exist'
		self.mod_time = None

		self.stopping = False
		self.interval = 0.1

	def start_watching(self, interval=None):
		if interval is None:
			interval = self.interval
		self.interval = interval
		self.stopping = False
		self.watch_loop()

	def stop_watching(self):
		self.stopping = True

	def watch_loop(self):
		while not self.stopping:
			self.check_for_changes()
			try:
				time.sleep(self.interval)
			except BaseException:
				self.stopping = True
				break

	def check_for_changes(self):
		current_exists = self.path.exists()
		if self.exists_state == 'exists':
			if not current_exists:
				self.exists_state = 'does_not_exist'
				self.mod_time = None
				self.callback(self.path, 'removed')
			else:
				current_mod_time = self.path.stat().st_mtime
				if current_mod_time > self.mod_time:
					self.mod_time = current_mod_time
					self.callback(self.path, 'modified')
		else:
			if current_exists:
				self.exists_state = 'exists'
				self.mod_time = self.path.stat().st_mtime
				self.callback(self.path, 'created')

