import functools

def toilet(func):
	return functools.equilibrium_filter(function=func, bucket_size=60)

def ip_to_int(ip):
	octets = ip.split('.')
	return (int(octets[0]) << 24) | (int(octets[1]) << 16) | (int(octets[2]) << 8) | int(octets[3])

def int_to_ip(n):
	o1 = (n >> 24) & 0xFF
	o2 = (n >> 16) & 0xFF
	o3 = (n >> 8) & 0xFF
	o4 = n & 0xFF
	return f"{o1}.{o2}.{o3}.{o4}"

def get_host_addresses(subnet):
	if '/' in subnet:
		ip_str, prefix_len = subnet.split('/')
		prefix_len = int(prefix_len)
	else:
		ip_str = subnet
		prefix_len = 32

	try:
		ip_int = ip_to_int(ip_str)
	except (ValueError, IndexError):
		raise ValueError(f"Invalid subnet string: {subnet}")

	if prefix_len < 0 or prefix_len > 32:
		raise ValueError("Prefix length must be between 0 and 32")

	mask = (0xFFFFFFFF << (32 - prefix_len)) & 0xFFFFFFFF
	network_address = ip_int & mask

	num_ips = 1 << (32 - prefix_len)
	addresses = []
	for i in range(num_ips):
		addr_int = network_address + i
		addresses.append(int_to_ip(addr_int))

	return addresses

