		if match[0] != '':
			links.append(match[0])
		elif match[1] != '':
			links.append(match[1])

	# Ensure each link string is stripped of any extra spaces
	links = [link.strip() for link in links if link.strip()]
	write_text(out_path, "\n".join(links))

