def list_subnet(subnet_str: str):
	parts = subnet_str.split('/')
	if len(parts) != 2:
		raise ValueError("Invalid subnet format")

	ip_str = parts[0]
	prefix_str = parts[1]

	if not ip_str:
		raise ValueError("Invalid IP address")

	try:
		prefix_len = int(prefix_str)
	except ValueError:
		raise ValueError("Invalid prefix length")

	if prefix_len < 0 or prefix_len > 32:
		raise ValueError("Prefix length must be between 0 and 32")

	ip_parts = ip_str.split('.')
	if len(ip_parts) != 4:
		raise ValueError("Invalid IP address format")

	try:
		ip = tuple(int(part) for part in ip_parts)
	except ValueError:
		raise ValueError("IP address parts must be integers")

	ip_int = (ip[0] << 24) | (ip[1] << 16) | (ip[2] << 8) | ip[3]

	mask = 0xFFFFFFFF << (32 - prefix_len) & 0xFFFFFFFF
	network_address = ip_int & mask

	host_count = 1 << (32 - prefix_len)

	if host_count > 1000000:
		raise ValueError(f"Subnet has {host_count} addresses, which is too large")

	addresses = []
	for i in range(host_count):
		addr_int = network_address | i
		a = (addr_int >> 24) & 0xFF
		b = (addr_int >> 16) & 0xFF
		c = (addr_int >> 8) & 0xFF
		d = addr_int & 0xFF
		addresses.append(f"{a}.{b}.{c}.{d}")

	return addresses

