from typing import List, Tuple

def convert_ip_to_int(ip: str) -> int:
	parts = list(map(int, ip.split('.')))
	if len(parts) != 4:
		raise ValueError(f"Invalid IP address: {ip}")
	return (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]

def list_subnet_addresses(base_ip: str, mask_length: int) -> List[str]:
	try:
		ip = convert_ip_to_int(base_ip)
	except ValueError:
		return []

	shift = 32 - mask_length
	if mask_length < 0 or mask_length > 32:
		raise ValueError("Mask length must be between 0 and 32")

	subnet_mask = ((1 << mask_length) - 1) << shift
	network_address = ip & subnet_mask
	num_addresses = 1 << shift

	if num_addresses > (1 << 16):
		return ["Too many addresses"]

	addresses = []
	for i in range(num_addresses):
		addr = network_address + i
		octet1 = (addr >> 24) & 0xFF
		octet2 = (addr >> 16) & 0xFF
		octet3 = (addr >> 8) & 0xFF
		octet4 = addr & 0xFF
		addresses.append(f"{octet1}.{octet2}.{octet3}.{octet4}")
	return addresses

