def compute_stats(values):
	if not values:
		return None

	n = len(values)
	mean_val = sum(values) / n

	sorted_vals = sorted(values)
	if n % 2 == 1:
		median_val = sorted_vals[n//2]
	else:
		median_val = (sorted_vals[n//2-1] + sorted_vals[n//2]) / 2.0

	counts = {}
	for val in values:
		counts[val] = counts.get(val, 0) + 1
	max_count = max(counts.values())
	mode_val = None
	for val in values:
		if counts[val] == max_count:
			mode_val = val
			break

	if n <= 1:
		variance_val = 0.0
	else:
		squared_diff = sum((x - mean_val) ** 2 for x in values)
		variance_val = squared_diff / (n-1)

	return {
		"mean": mean_val,
		"median": median_val,
		"mode": mode_val,
		"variance": variance_val
	}

