import collections

def build_topological_order(dependencies):
	if not dependencies:
		return []

	all_tasks = set()
	for dep in dependencies:
		_, t = dep
		all_tasks.add(t)

	if not all_tasks:
		return []

	graph = {}
	in_degree = {}
	for task in all_tasks:
		graph[task] = []
		in_degree[task] = 0

	for dep in dependencies:
		p, t = dep
		graph[p].append(t)
		in_degree[t] += 1

	q = collections.deque()
	for task in all_tasks:
		if in_degree[task] == 0:
			q.append(task)

	result = []
	while q:
		task = q.popleft()
		result.append(task)
		for dependent in graph[task]:
			in_degree[dependent] -= 1
			if in_degree[dependent] == 0:
				q.append(dependent)

	if len(result) != len(all_tasks):
		raise ValueError("Cycle detected. The dependency graph has a cycle.")

	return result

