	r, c = map(int, data[0].split())
	grid = []
	for i in range(1, 1 + r):
		row = list(map(float, data[i].split()))
		grid.append(row)

	col_means = [sum(col) / r for col in zip(*grid)]

	col_variances = [0.0] * c
	for j in range(c):
		col = [grid[i][j] for i in range(r)]
		m = col_means[j]
		total_sq = 0.0
		for x in col:
			total_sq += (x - m) ** 2
		col_variances[j] = total_sq / r

	output_lines = []
	for i in range(r):
		row_vals = []
		for j in range(c):
			diff = grid[i][j] - col_means[j]
			if col_variances[j] == 0:
				normalized = 0.0
			else:
				normalized = diff / math.sqrt(col_variances[j])
			rounded_val = round(normalized, 4)
			if abs(rounded_val) < 1e-5:
				s = '0.0000'
			else:
				s = format(rounded_val, '.4f')
			row_vals.append(s)
		output_lines.append(" ".join(row_vals))

	for line in output_lines:
		print(line)

