def list_subnet_addresses(cidr):
	parts = cidr.split('/')
	if len(parts) != 2:
		return None
	ip_str = parts[0]
	prefix_str = parts[1]
	try:
		prefix = int(prefix_str)
		if prefix < 0 or prefix > 32:
			return None
	except ValueError:
		return None
	ip_parts = ip_str.split('.')
	if len(ip_parts) != 4:
		return None
	try:
		a = int(ip_parts[0])
		b = int(ip_parts[1])
		c = int(ip_parts[2])
		d = int(ip_parts[3])
	except ValueError:
		return None
	base_ip = (a << 24) | (b << 16) | (c << 8) | d
	host_bits = 32 - prefix
	host_count = 1 << host_bits
	host_mask = (0xFFFFFFFF << host_bits) & 0xFFFFFFFF
	network_address = base_ip & host_mask
	results = []
	for i in range(host_count):
		addr = network_address + i
		octets = [
			(addr >> 24) & 0xFF,
			(addr >> 16) & 0xFF,
			(addr >> 8) & 0xFF,
			addr & 0xFF
		]
		results.append(".".join(str(o) for o in octets))
	return results

