def flatten(iterable):
	result = []
	for item in iterable:
		if isinstance(item, (str, bytes)):
			result.append(item)
		else:
			try:
				it = iter(item)
				for subitem in it:
					result.append(subitem)
			except TypeError:
				result.append(item)
	return result

