import ast

class FlattenCommand:
	"""Flattens a list of lists into a single sequence."""

	def __init__(self):
		pass

	def __call__(self, sequence: str) -> list:
		try:
			lst = ast.literal_eval(sequence)
		except Exception as e:
			raise ValueError(f"Error parsing input: {e}")
		result = self._flatten(lst)
		return result

	def _flatten(self, lst):
		"""Flattens one level of nested lists in to a single sequence.

		Args:
			lst: List to flatten (containing other lists).

		Returns:
			A single flat list containing all elements from the input list.
		"""
		flat = []
		for item in lst:
			if type(item) is list:
				flat.extend(item)
			else:
				flat.append(item)
		return flat

