from typing import List, Tuple

def cluster_points(points: List[Tuple[float, float]], radius: float, min_group_size: int = 2) -> List[List[Tuple[float, float]]]:
	if not points:
		return []

	points_sorted = sorted(points, key=lambda p: (p[0], p[1]))
	n = len(points_sorted)
	r_sq = radius * radius
	graph = [[] for _ in range(n)]

	for i in range(n):
		for j in range(i+1, n):
			dx = points_sorted[j][0] - points_sorted[i][0]
			if dx * dx > r_sq:
				break
			dy = points_sorted[j][1] - points_sorted[i][1]
			if dx * dx + dy * dy <= r_sq:
				graph[i].append(j)
				graph[j].append(i)

	visited = [False] * n
	clusters = []

	for i in range(n):
		if not visited[i]:
			stack = [i]
			visited[i] = True
			cluster = [points_sorted[i]]
			while stack:
				idx = stack.pop()
				for neighbor in graph[idx]:
					if not visited[neighbor]:
						visited[neighbor] = True
						stack.append(neighbor)
						cluster.append(points_sorted[neighbor])
			if len(cluster) >= min_group_size:
				clusters.append(cluster)

	return clusters

