def one_hot_encode(category_list: List[str], categories: List[str]) -> np.ndarray:
	if not categories:
		return np.zeros((1, 0), dtype=np.float64)

	categories_set = set(category_list)
	mask = [1.0 if c in categories_set else 0.0 for c in categories]
	return np.array(mask, dtype=np.float64).reshape((1, len(categories)))

def one_hot_encode(rows, categories):
	mapping = {cat: idx for idx, cat in enumerate(categories)}
	result = []
	for row in rows:
		vec = [0] * len(categories)
		for cat in row:
			if cat in mapping:
				vec[mapping[cat]] = 1
		result.append(vec)
	return result

