def normalize_values(values: List[int]) -> List[float]:
	if len(values) == 0:
		return []
	mean = sum(values) / len(values)
	std = (sum((x - mean) ** 2 for x in values) / len(values)) ** 0.5
	normalized = []
	for x in values:
		if std == 0:
			normalized.append(0.0)
		else:
			normalized.append((x - mean) / std)
	return normalized

