	job: Job,
	file: File
) -> Response:
	job_in_jobs = None
	for j in jobs:
		if j['id'] == job_id:
			job_in_jobs = j
			break
	if job_in_jobs is None:
		return Response("Job not found", status_code=404)
	data = pd.read_csv(file.value)
	job['group_col'] = job_in_jobs['group_col']
	job['std_col'] = job_in_jobs['std_col']

	if job['group_col'] is not None and job['std_col'] is not None and job['std_col'] in data:
		grouped = data.groupby(job['group_col'])
		new_data = data.copy()
		for name, df in grouped:
			s = df[job['std_col']]
			if s.empty:
				continue
			mean = s.mean()
			std = s.std(ddof=0)
			if std == 0:
				continue
			s_normalized = (s - mean) / std
			new_data[job['std_col']] = s_normalized
	result_content = new_data.to_csv(index=False)
	return Response(result_content, status_code=200)

