def standardize_column(df, group_col, target_col):
	def transform_series(x):
		std = x.std()
		if std == 0:
			return x
		return (x - x.mean()) / std

	df[target_col] = df.groupby(group_col)[target_col].transform(transform_series)
	return df

import pandas as pd

def standardize_column(dataframe, group_col, value_col):
	if dataframe.empty:
		return dataframe

	result = dataframe.copy()
	grouped = dataframe.groupby(group_col)

	for name, group in grouped:
		if len(group) > 1:
			values = group[value_col]
			mean = values.mean()
			std = values.std(ddof=0)
			result[value_col] = values.map(lambda x: (x - mean) / std)

	return result

