import time
import threading

def slow(func):
	if not hasattr(func, 'lock'):
		func.lock = threading.Lock()
	def wrapper(*args, **kwargs):
		current_time = time.time()
		with func.lock:
			if not hasattr(func, 'last_run'):
				func.last_run = current_time
				return func(*args, **kwargs)
			else:
				last_run = func.last_run
				if current_time - last_run >= 60:
					func.last_run = current_time
					return func(*args, **kwargs)
				else:
					return None
	return wrapper

