		if not hasattr(func, 'last_run'):
			result = func(*args, **kwargs)
			func.last_run = current_time
			return result
		else:
			last_run = func.last_run
			if current_time >= last_run + 60:
				result = func(*args, **kwargs)
				func.last_run = current_time
				return result
			else:
				return None
	return wrapper

