def curry_calls(period=60):
	def wrapper(func):
		if not hasattr(wrapper, 'last_seen'):
			wrapper.last_seen = None
		now = time.time()
		if wrapper.last_seen is None or now - wrapper.last_seen >= period:
			wrapper.last_seen = now
			return func
		return None
	return wrapper

