from sklearn.cluster import DBSCAN
from collections import defaultdict

def group_points(points, radius, min_group_size):
	n = len(points)
	if n == 0:
		return []

	points_array = np.array(points)

	dbsc = DBSCAN(eps=radius, min_samples=min_group_size)
	dbsc.fit(points_array)
	labels = dbsc.labels_

	cluster_indices = defaultdict(list)
	for idx, label in enumerate(labels):
		if label != -1:
			cluster_indices[label].append(idx)

	result = [-1] * n
	new_id = 0
	for label, indices in cluster_indices.items():
		if len(indices) >= min_group_size:
			for idx in indices:
				result[idx] = new_id
			new_id += 1

	return result

from collections import deque
from sklearn.neighbors import KDTree

def cluster_points(points, radius, min_size):
	n = len(points)
	if n == 0:
		return []

	tree = KDTree(points)
	visited = [False] * n
	labels = [-1] * n
	current_label = 0

	for i in range(n):
		if not visited[i]:
			component = []
			queue = deque([i])
			visited[i] = True
			while queue:
				node = queue.popleft()
				component.append(node)
				neighbors = tree.query_ball_point(points[node], radius, return_distance=False)
				for j in neighbors:
					if not visited[j]:
						visited[j] = True
						queue.append(j)
			if len(component) >= min_size:
				for idx in component:
					labels[idx] = current_label
				current_label += 1
	return labels

