from typing import Optional, Tuple, List

def parse_log_line(line: str) -> Optional[Tuple[str, str, str, List[str], str]]:
	tokens = line.split(maxsplit=2)
	if len(tokens) < 3:
		return None

	ts_str = tokens[0]
	level = tokens[1]
	rest = tokens[2]

	try:
		dt = datetime.datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
	except Exception:
		return None

	if ' -> ' in rest:
		idx = rest.find(' -> ')
		if idx == -1:
			return None
		base_message = rest[:idx]
		after = rest[idx+3:]

		if after.startswith('{') and after.endswith('}'):
			trace_str = after[1:-1]
			trace_list = [x.strip() for x in trace_str.split(',')]
			output = after[1:-1].strip()
			return (ts_str, level, base_message, trace_list, output)
		return None
	else:
		return (ts_str, level, rest, [], None)

