import pandas as pd
from itertools import groupby

def standardize_column(df, group_col, std_col):
	grouped = df.groupby(group_col)
	result = []
	for key, group in grouped:
		col = group[std_col]
		n = len(col)
		if n == 1:
			group[std_col] = 0
		else:
			mean_val = col.mean()
			std_val = col.std(ddof=0)
			group[std_col] = (col - mean_val) / std_val
		result.append(group)
	return pd.concat(result)

