	if not isinstance(path, Path):
		path = Path(path)

	try:
		with ZipFile(path) as zipf:
			return sorted([Path(entry.name) for entry in zipf if entry.isfile()])
	except (OSError, zipfile.BadZipfile, zipfile.IncompleteRead):
