		if n == 0:
			result[col] = (None, None, None, None)
		else:
			total = sum(col_data)
			mean = total / n

			sorted_col = sorted(col_data)
			if n % 2 == 1:
				median = sorted_col[n // 2]
			else:
				median = (sorted_col[n // 2 - 1] + sorted_col[n // 2]) / 2

			freq = {}
			for x in col_data:
				freq[x] = freq.get(x, 0) + 1
			max_freq = max(freq.values())
			mode = None
			for item in col_data:
				if freq[item] == max_freq:
					mode = item
					break

			if n == 1:
				variance = 0.0
			else:
				variance = sum((x - mean) ** 2 for x in col_data) / (n - 1)

			result[col] = (mean, median, mode, variance)

	return result

def compute_stats(table):
	if not table or len(table) == 0:
		return []
	n = len(table)
	if n == 0:
		return []
	if len(table[0]) == 0:
		return []
	num_cols = len(table[0])

	result = []
	for j in range(num_cols):
		col = [table[i][j] for i in range(n)]

		mean = sum(col) / n

		sorted_col = sorted(col)
		mid = n / 2.0
		if n % 2 == 0:
			median = (sorted_col[mid-1] + sorted_col[mid]) / 2
		else:
			median = sorted_col[mid]

		freq = {}
		for x in col:
			freq[x] = freq.get(x, 0) + 1

		max_freq = max(freq.values())
		mode = min(val for val, count in freq.items() if count == max_freq)

		squared_diffs = [(x - mean) ** 2 for x in col]
		variance = sum(squared_diffs) / n

		result.append({
			'mean': mean,
			'median': median,
			'mode': mode,
			'variance': variance
		})

	return result

