from datetime import timezone, datetime, timedelta

def bucket_by_hour(events):
	result = {}
	for event in events:
		ts, tz_str = event[0], event[1]

		if tz_str == 'UTC':
			tz = timezone.utc
		else:
			if tz_str[0] in ('+', '-'):
				if len(tz_str) == 6 and tz_str[1:].isdigit():
					sign_char = tz_str[0]
					hours = int(tz_str[1:3])
					minutes = int(tz_str[3:5])
					offset_seconds = (hours * 3600) + (minutes * 60)
					if sign_char == '+':
						offset = timedelta(seconds=offset_seconds)
					else:
						offset = timedelta(seconds=-offset_seconds)
					tz = timezone(offset)
				else:
					try:
						time_parts = tz_str.split(':')
						sign_part = time_parts[0]
						time_str = time_parts[1]
						if len(time_parts) > 2:
							continue
						hours = int(sign_part[1:]) if sign_part.startswith(('+', '-')) else 0
						minutes = int(time_str)
						offset_seconds = (hours * 3600) + (minutes * 60)
						if sign_part.startswith('+'):
							offset = timedelta(seconds=offset_seconds)
						else:
							offset = timedelta(seconds=-offset_seconds)
						tz = timezone(offset)
					except:
						tz = timezone.utc
			else:
				try:
					hours = int(tz_str)
					offset_seconds = hours * 3600
					tz = timezone(timedelta(seconds=offset_seconds))
				except:
					tz = timezone.utc

		try:
			dt = datetime.fromtimestamp(ts, tz=tz)
		except Exception as e:
			tz = timezone.utc
			dt = datetime.fromtimestamp(ts, tz=tz)

		hour = dt.hour
		if hour not in result:
			result[hour] = []
		result[hour].append(ts)

	return result

def resolve_dependencies(dependency_pairs):
	graph = {}
	in_degree = {}
	nodes = set()

	for pair in dependency_pairs:
		A = pair[0]
		B = pair[1]
		nodes.add(A)
		nodes.add(B)
		if B not in graph:
			graph[B] = []
		graph[B].append(A)
		in_degree[A] = in_degree.get(A, 0) + 1

	for node in nodes:
		if node not in in_degree:
			in_degree[node] = 0

	queue = sorted([node for node in nodes if in_degree[node] == 0])
	topo_order = []

	while queue:
		node = queue.pop(0)
		topo_order.append(node)
		if node in graph:
			for neighbor in graph[node]:
				in_degree[neighbor] -= 1
				if in_degree[neighbor] == 0:
					queue.append(neighbor)

	if len(topo_order) != len(nodes):
		raise ValueError("Cycle detected")

	return topo_order

import collections

def topological_sort(dependencies: list[tuple]) -> list:
	if not dependencies:
		return []

	nodes = set()
	for a, b in dependencies:
		nodes.add(a)
		nodes.add(b)

	graph = {}
	in_degree = {node: 0 for node in nodes}

	for a, b in dependencies:
		if b not in graph:
			graph[b] = []
		graph[b].append(a)
		in_degree[a] += 1

	queue = collections.deque()
	for node in nodes:
		if in_degree[node] == 0:
			queue.append(node)

	order = []
	while queue:
		node = queue.popleft()
		order.append(node)
		if node in graph:
			for neighbor in graph[node]:
				in_degree[neighbor] -= 1
				if in_degree[neighbor] == 0:
					queue.append(neighbor)

	if len(order) != len(nodes):
		raise ValueError("Cycle detected")

	return order

